def copy_axle_fields_to_parameters(apps, schema_editor):
    """Move old axle columns into ProductSpecValue rows of each product's category.

    Missing parameters are created on the product's category so no value is
    lost. Free-text measurements such as '4"' are kept as text when they
    cannot be read as a plain number.
    """
    import re

    Product = apps.get_model("catalog", "Product")
    AxleSpec = apps.get_model("catalog", "AxleSpec")
    SpecField = apps.get_model("catalog", "SpecField")
    ProductSpecValue = apps.get_model("catalog", "ProductSpecValue")
    if not Product.objects.exists():
        return

    def field_for(category, key, kind, label):
        field = SpecField.objects.filter(category=category, key=key).first()
        if field:
            return field
        data_type = {"capacity": "number", "dimension": "number", "choice": "text", "text": "text", "text_number": "text"}[kind]
        quantity = {"capacity": "mass", "dimension": "length"}.get(kind, "")
        return SpecField.objects.create(
            category=category, key=key, label=label, data_type=data_type, quantity=quantity,
            filterable=kind in {"capacity", "dimension", "choice"}, show_on_card=key in {"rated_capacity", "axle_type", "brake_type", "bolt_pattern"},
            ask_in_rfq=False, used_by_products=True, position=SpecField.objects.filter(category=category).count() * 10,
        )

    def store(product, field, kind, raw, dimension_unit, capacity_unit):
        if raw in (None, ""):
            return
        values = {"number_value": None, "entered_unit": "", "base_value": None, "text_value": "", "boolean_value": None}
        if kind == "capacity":
            number = Decimal(raw)
            values.update(number_value=number, entered_unit=capacity_unit, base_value=number * LB_TO_KG if capacity_unit == "lb" else number)
        elif kind == "dimension":
            number = Decimal(raw)
            values.update(number_value=number, entered_unit=dimension_unit, base_value=number * IN_TO_MM if dimension_unit == "in" else number)
        else:
            text = OLD_CHOICE_LABELS.get(str(raw), str(raw))
            match = re.fullmatch(r"\s*(\d+(?:\.\d+)?)\s*", text) if kind == "text_number" else None
            values["text_value"] = text[:255]
            if match and field.data_type == "number":
                values.update(text_value="", number_value=Decimal(match.group(1)))
        ProductSpecValue.objects.update_or_create(product=product, field=field, defaults=values)

    for product in Product.objects.select_related("category"):
        spec = AxleSpec.objects.filter(product=product).first()
        sources = [(product, AXLE_PRODUCT_FIELDS)] + ([(spec, AXLE_SPEC_FIELDS)] if spec else [])
        for source, mapping in sources:
            for column, (key, kind) in mapping.items():
                raw = getattr(source, column)
                if raw in (None, ""):
                    continue
                field = field_for(product.category, key, kind, column.replace("_", " ").capitalize())
                if field.data_type == "choice" and OLD_CHOICE_LABELS.get(str(raw), str(raw)) not in (field.choices or []):
                    kind = "text"
                store(product, field, kind, raw, product.dimension_unit, product.capacity_unit)
        for column in ("moq", "lead_time", "loading_port"):
            if spec and getattr(spec, column):
                setattr(product, column, getattr(spec, column))
        product.save(update_fields=["moq", "lead_time", "loading_port"])


